"""Build the local stock shortlist and keep rejected/blocked items visible on request."""
import html,json,pathlib
p=pathlib.Path(__file__).resolve().parent;rows=json.loads((p/'catalogue.json').read_text());e=html.escape;cards=[]
labels={'shortlist':'Seçki · sahneye göre kullan','rejected':'Elendi','blocked':'Kontrol eksik'}
for r in sorted(rows,key=lambda r:({'shortlist':0,'rejected':1,'blocked':2}[r['selection']],r['display_title'])):
 frames=r.get('frames',[]);poster=frames[0] if frames else None
 media=f'<video controls muted playsinline preload="none" poster="{e(poster or "")}" src="{e(r["preview"])}"></video>' if r.get('preview') else '<div class="missing">Görüntü kontrolü bekliyor</div>'
 if r.get('kind')=='image': media=f'<img src="{e(r["preview"])}" alt="{e(r["display_title"])}" loading="lazy">'
 cards.append(f'''<article data-state="{r['selection']}" data-search="{e((r['display_title']+' '+r['title']+' '+r.get('visual_note','')).lower())}"><small>{labels[r['selection']]}</small><h2>{e(r['display_title'])}</h2>{media}<p>{e(r['visual_note'])}</p><details><summary>Lisans ve inceleme</summary><p>{e(r['rights_note'])}</p><p>{e(r.get('method',''))}</p><p>{e(r.get('licenseLabel',''))} · {e(r.get('creator',''))}</p><a href="{e(r['page'])}" target="_blank" rel="noreferrer">Orijinal kaynak</a> · <a href="{e(r.get('licenseUrl') or r['page'])}" target="_blank" rel="noreferrer">Lisans</a><p>{e(r['ref'])} · {e(r['batch'])}</p></details></article>''')
page='''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Film-lab · Stok seçkisi</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f1eb;color:#242a25;font:16px system-ui}header,nav,main{padding:24px 5vw}h1{font-size:36px;margin:8px 0}header p{max-width:900px;line-height:1.6}nav{display:flex;gap:12px;flex-wrap:wrap;border-block:1px solid #b9bcae;position:sticky;top:0;background:#f3f1eb;z-index:1}input,select{font:inherit;padding:12px;border:1px solid #8c9785;background:white}input{flex:1;min-width:180px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:24px}article{padding:18px;background:#fff;border:1px solid #c3c9bc}article[hidden]{display:none}video,img,.missing{width:100%;height:220px;background:#191e19;object-fit:contain}.missing{display:grid;place-items:center;color:white}h2{font-size:21px}p{line-height:1.5}details{font-size:14px}summary{cursor:pointer}a{color:#31562b}small{color:#53644c}#count{align-self:center}</style><header><small>FILM-LAB / 28 EKİM KONTROLÜ</small><h1>Hikâyeye göre stok.</h1><p>11 görüntü seçkide: 9 video ve 2 doku. Yeni aramalar ve eski yerel adaylar ayrı etiketli. Kaynak lisansı ve örnek kareler kontrol edildi; bu, her sahne için sınırsız hak onayı değildir. Sesler seçilmedi. Videoyu burada açıp hareketi değerlendir.</p><p>Fabrika görüntüleri korundu. Yeni geliştirici, telefon, çalışma ortamı ve ışık klipleri ile mevcut kâğıt/kumaş dokuları eklendi. Erişim sınırına takılanları incelemiş gibi göstermiyoruz. Eski çömlek klibinin ücretsiz sürümü ticari kullanıma kapalı; seçkiden çıkarıldı. Bu sayfa yerel inceleme içindir, ham stok dağıtım sitesi değildir.</p><a href="../../FILM_FLOW.md">Film üretim akışı</a></header><nav><input id="q" aria-label="Görüntülerde ara" placeholder="Robot, telefon, klavye…"><select id="state" aria-label="Kontrol durumu"><option value="shortlist">Seçki</option><option value="">Hepsi</option><option value="rejected">Elenenler</option><option value="blocked">Kontrol eksik</option></select><span id="count" aria-live="polite"></span></nav><main>CARDS</main><script>const q=document.querySelector('#q'),state=document.querySelector('#state'),cards=[...document.querySelectorAll('article')];function filter(){let n=0;for(const c of cards){c.hidden=!(c.dataset.search.includes(q.value.toLowerCase())&&(!state.value||state.value===c.dataset.state));if(!c.hidden)n++}document.querySelector('#count').textContent=n+' kayıt'}q.oninput=state.onchange=filter;filter();document.addEventListener('play',e=>{for(const v of document.querySelectorAll('video'))if(v!==e.target)v.pause()},true)</script></html>'''.replace('CARDS',''.join(cards));(p/'index.html').write_text(page)
assert len({r['ref'] for r in rows})==len(rows)
print(f'Built {len(rows)} records')
